function rchat(){var t=document.getElementById("chatThread");if(!t||cs===0)return;t.querySelectorAll(".chat-message--host").forEach(function(el){if(!el.closest("#chatOpening"))el.remove();});var cur=cs;cs=0;var f=CHAT[S.lang]||CHAT.zh;for(var i=0;i<cur&&i<f.length;i++){hm(f[i]);cs++;}if(cs>=f.length){hm(t("chatEnd"));var g=document.getElementById("guideOptions");if(g){g.hidden=false;t.append(g);}var h=document.getElementById("chatHint");if(h)h.hidden=true;}else{var h2=document.getElementById("chatHint");if(h2)h2.hidden=false;uhint();}}const CHAT={zh:["故事起于一个偶然的下午。","朋友 Geometry 带我认识了 LaTeX 和 Overleaf。","我也是从那里注意到「文学化编程」。","学术与技术并不是两条互不相干的路。","程序员、作家和设计师这几种身份在我身上并不冲突。","我喜欢有个性的叙事，偶尔添一点古风。","形式再漂亮也要装得下真正有价值的想法。","我想保存自己的故事和身边人的故事。","青春里不同人的念头会彼此遇见。","纸本、公开动态、聊天记录都可以成为记忆的容器。","有趣的内容很容易溜走；当时不记后来只剩模糊的影子。","只要一件事足够有趣就值得被认真记录。","记录不是把来路修饰得完美。","这里会有小短文、札记和旅行攻略。","我担心记忆在时间里逐渐破碎。","初三以后我慢慢形成了整理语言和笔记的习惯。","2024年新的技能把这个习惯推向了更完整的系统。","我珍惜那些给我宽容和陪伴的伙伴。","书单里有《魔戒》、Linux、Python和《编码》。","愿为江水，与君同行。"],en:["It all started on a casual afternoon.","My friend Geometry introduced me to LaTeX and Overleaf.","That's where I noticed 'literate programming'.","Academics and technology aren't separate paths.","Programmer, writer, designer — these roles coexist in me.","I enjoy storytelling with character, sometimes with a classic touch.","Beautiful form must hold truly valuable ideas.","I want to preserve my own stories and those around me.","Different people's thoughts meet in youth.","Notebooks, public posts, chat logs — all can be vessels of memory.","Interesting things slip away easily; if not written down, only blurry shadows remain.","Anything interesting enough deserves to be recorded.","Recording is not about perfecting the past.","Here you'll find short essays, notes, and travel guides.","I worry about memories shattering over time.","After ninth grade I slowly built a habit of organizing language and notes.","New skills in 2024 pushed this habit into a more complete system.","I cherish those who gave me patience and company.","My reading list includes Lord of the Rings, Linux, Python, and Code.","Like rivers flowing, I walk with you."],fr:["Tout a commencé un après-midi ordinaire.","Mon ami Geometry m'a fait découvrir LaTeX et Overleaf.","C'est là que j'ai remarqué la «programmation lettrée».","Le savoir et la technique ne sont pas des chemins séparés.","Programmeur, écrivain, designer — ces rôles coexistent en moi.","J'aime les récits avec du caractère, parfois une touche classique.","Une belle forme doit contenir des idées vraiment précieuses.","Je veux préserver mes histoires et celles de mon entourage.","Les pensées de différentes personnes se croisent dans la jeunesse.","Carnets, posts publics, discussions — tout peut devenir réceptacle de mémoire.","Les choses intéressantes s'échappent facilement; sans trace, il ne reste que des ombres floues.","Tout ce qui est assez intéressant mérite d'être enregistré.","Enregistrer n'est pas embellir le passé.","Ici vous trouverez de courts essais, des notes et des guides de voyage.","Je crains que les souvenirs ne se brisent avec le temps.","Après la troisième, j'ai lentement pris l'habitude d'organiser la langue et les notes.","De nouvelles compétences en 2024 ont poussé cette habitude vers un système plus complet.","Je chéris ceux qui m'ont offert patience et compagnie.","Ma liste de lecture comprend Le Seigneur des Anneaux, Linux, Python et Code.","Comme les rivières qui coulent, je marche avec toi."],de:["Alles begann an einem gewöhnlichen Nachmittag.","Mein Freund Geometry führte mich in LaTeX und Overleaf ein.","Dort bemerkte ich das 'literate programming'.","Wissenschaft und Technik sind keine getrennten Wege.","Programmierer, Autor, Designer — diese Rollen koexistieren in mir.","Ich mag Erzählungen mit Charakter, manchmal mit klassischem Touch.","Schöne Form muss wirklich wertvolle Ideen enthalten.","Ich möchte meine eigenen Geschichten und die meiner Umgebung bewahren.","Die Gedanken verschiedener Menschen treffen sich in der Jugend.","Notizbücher, öffentliche Beiträge, Chat-Protokolle — alles kann Gefäße der Erinnerung sein.","Interessante Dinge entgleiten leicht; ohne Aufzeichnung bleiben nur verschwommene Schatten.","Alles, was interessant genug ist, verdient es, festgehalten zu werden.","Aufzeichnen bedeutet nicht, die Vergangenheit zu verschönern.","Hier finden Sie kurze Essays, Notizen und Reiseführer.","Ich fürchte, dass Erinnerungen mit der Zeit zerbrechen.","Nach der neunten Klasse entwickelte ich langsam die Gewohnheit, Sprache und Notizen zu ordnen.","Neue Fähigkeiten im Jahr 2024 brachten diese Gewohnheit in ein vollständigeres System.","Ich schätze jene, die mir Geduld und Gesellschaft schenkten.","Meine Leseliste umfasst Herr der Ringe, Linux, Python und Code.","Wie fließende Flüsse gehe ich mit dir."]};

document.querySelectorAll("#guideOptions [data-guide]").forEach(function(b){b.onclick=function(){var g=this.dataset.guide;if(g==="recent"||g==="living"){gm(this.textContent.trim());setTimeout(function(){sw("now");},600);}else if(g==="treasures"){gm(this.textContent.trim());setTimeout(function(){sw("album");},600);}else if(g==="wander"){gm(this.textContent.trim());setTimeout(function(){sw("journal");},600);}else if(g==="anniversary"){gm((this.querySelector("span:last-child")||this).textContent.trim());var as=S.lang==="en"?{"2026-08-01":["I flipped open today's journal.","August 1st. High summer in Lianxi.","Today I maintained my own website.","Even updated some little details, polishing here and there.","Watched Rick and Morty commentary. Really satisfying.","Breakfast was just noodles. Simple.","Lunch was fried rice made from yesterday's leftovers.","Third Uncle took us to Wanda Plaza for bullfrog and shrimp.","A lobster scale got stuck on my tonsil. Nearly choked to death.","Showering at night, I heard Third Uncle question my cousin about his studies.","My cousin had zero confidence in his schoolwork.","Got yelled at by his dad again, even sobbed a little.","Poor kid. He even promised to study more every day from now on.","But my girl cousin is much cleverer. She knows how to handle her dad.","Third Uncle is super satisfied with his daughter, gets a headache seeing his son.","I even suspect Third Uncle just likes his daughter better.","Late at night, my girl cousin suddenly came to sleep in the big room.","She told me: while talking back to her dad, she accidentally farted at his head.","Because he was lying in bed, and she stood by the bedside. That takes guts.","And that was today's tea talk."],"2026-08-02":["I flipped open today's journal.","August 2nd. Summer in Lianxi continues.","Boiled instant noodles and dried noodles together in the morning.","Instant plus dried. A combo only I would invent.","Bound my own domain newtnorlly.xyz in the afternoon.","It went through instantly. Way smoother than I expected.","Then my cousin took me and her son to the arcade.","My nephew got first place on the racing cabinet, beaming with pride.","In the car, he climbed from the back to pat my head.","Like I was his nephew. Roles completely reversed.","Used two WeChat accounts to score him 40 free game tokens.","My cousin and her bestie went shopping, left my nephew with me.","He's so noisy—my cousin avoids bringing him shopping if she can.","After Chuanchuanxiang, my cousin drove me home.","My nephew kept asking from the back seat: Uncle, come to my place?","His mom taught him a trick: ask Uncle about the last few days before school.","So he kept asking me exactly that, copying his mom.","I was so touched. I just said yes right away.","Honestly, these days I'm not that excited when people invite me out.","But through the phone, my nephew's voice kept calling: Uncle, Uncle, Uncle.","I couldn't help myself. Tears welled up from deep inside.","I shouldn't have kids too easily. What if they're as adorable as Gan Dengdeng?","Gan Dengdeng is my nephew's nickname. My whole life would be taken over.","Evening: Yulin Chuanchuanxiang. That's the restaurant's name.","Couldn't find a public restroom on the way back.","My uncle brought a bucket of chicken drumettes from Sugeli Island.","Watched Rick and Morty commentary. The Phoenix Protocol episode.","Rick set up decoy families way early as fake targets.","Enemies hit the decoys. Rick's real self stays untouched.","And that was today's tea talk."],"2026-07-31":["I flipped open today's journal.","July 31st. Summer in Lianxi is still hanging on.","Got up past 11 today. Slept in deep.","The funniest thing: my cousin was secretly gaming on his phone at midnight, headphones on.","His mom pushed the door open to check on us and saw the phone glow instantly.","My cousin panicked, tossed the phone aside, and pretended to be fast asleep.","So this morning his dad sanctioned him and dragged him to the construction site.","My other cousin and I laughed until our stomachs hurt.","Honestly, we felt so relieved it wasn't us.","In the afternoon, I studied German, French, and English indoors.","Also maintained two website projects and fixed the calendar year-view bug.","Today's motto: keep moving, eat plenty of meat.","A crafty rabbit has three burrows. That's been on my mind all day.","Every resource around you should be treated as compound interest, not as kindling.","Compound interest builds. Kindling just burns.","Stardew Valley is for idle days. When you have real projects, don't get lost in games.","Short video scrolling makes people dumb. My little cousin is living proof.","I asked her if she was a little dumber than me. She actually nodded.","So I'm eating well, learning web scraping, and deploying tasks to GitHub Actions.","Life's span is not ordained by heaven alone. Nurture your well-being, and you shall have long years. That's today's tea talk."]}:S.lang==="fr"?{"2026-08-01":["J'ai ouvert le journal d'aujourd'hui.","1er août. Plein été à Lianxi.","Aujourd'hui j'ai maintenu mon site web.","Même mis à jour quelques détails, polissant par-ci par-là.","Regardé des analyses de Rick and Morty. Vraiment satisfaisant.","Petit-déjeuner : juste des nouilles. Simple.","Déjeuner : riz sauté avec les restes d'hier.","Troisième Oncle nous a emmenés au Wanda pour de la grenouille et des crevettes.","Une écaille de queue de langoustine coincée sur l'amygdale. J'ai failli m'étouffer.","Sous la douche le soir, j'entendais Troisième Oncle questionner mon cousin.","Mon cousin n'avait aucune confiance dans ses devoirs.","Il s'est fait engueuler par son père, avec des petits sanglots.","Pauvre gamin. Il a même promis d'étudier plus chaque jour.","Mais ma petite cousine est bien plus maligne. Elle gère son père à merveille.","Troisième Oncle est super content de sa fille, mal à la tête avec son fils.","Je soupçonne que Troisième Oncle préfère tout simplement sa fille.","Tard dans la nuit, ma petite cousine est venue dormir dans la grande chambre.","Elle m'a dit : en répliquant à son père, elle a pété sur sa tête par accident.","Parce qu'il était couché et elle debout près du lit. Faut du cran.","Voilà, c'était le thé du jour."],"2026-08-02":["J'ai ouvert le journal d'aujourd'hui.","2 août. L'été à Lianxi continue.","Nouilles instantanées et sèches bouillies ensemble ce matin.","Instant plus sec. Un mélange qu'il n'y a que moi pour inventer.","Lié mon propre domaine newtnorlly.xyz cet après-midi.","C'est passé tout de suite. Bien plus fluide que prévu.","Puis ma cousine m'a emmené avec son fils à la salle d'arcade.","Mon neveu a fini premier sur la borne de course, tout fier.","Dans la voiture, il a grimpé de l'arrière pour me tapoter la tête.","Comme si c'était moi son neveu. Les rôles complètement inversés.","J'ai utilisé deux comptes WeChat pour lui avoir 40 jetons gratuits.","Ma cousine et sa meilleure amie faisaient du shopping, m'ont laissé le petit.","Il est tellement bruyant—ma cousine évite de l'emmener faire les magasins.","Après le Chuanchuanxiang, ma cousine m'a ramené en voiture.","Mon neveu n'arrêtait pas de demander depuis la banquette : Tonton, tu viens chez moi ?","Sa maman lui a appris une astuce : demande-lui pour les derniers jours avant l'école.","Alors il répétait ça, copiant sa maman.","J'étais tellement touché. J'ai tout de suite dit oui.","Honnêtement, en ce moment, sortir ne m'excite pas vraiment.","Mais au téléphone, la voix de mon neveu : Tonton, Tonton, Tonton.","Je n'ai pas pu me retenir. Les larmes sont venues du plus profond.","Faudra pas faire d'enfant trop facilement. Imaginez un aussi adorable que Gan Dengdeng.","Gan Dengdeng, c'est le surnom de mon neveu. Ma vie serait envahie.","Soir : Chuanchuanxiang de Yulin. C'est le nom du resto.","Pas trouvé de toilettes publiques sur le chemin du retour.","Mon oncle a ramené un seau de pilons de poulet de l'île de Sugeli.","Regardé une analyse de Rick and Morty. L'épisode du Protocole Phénix.","Rick avait préparé des familles leurres comme fausses cibles depuis longtemps.","Les ennemis tapent sur les leurres. Le vrai Rick reste intouché.","Voilà, c'était le thé du jour."],"2026-07-31":["J'ai ouvert le journal d'aujourd'hui.","31 juillet. L'été à Lianxi s'attarde encore.","Levée après 11 heures. J'ai dormi profondément.","Le plus drôle : mon cousin jouait en cachette sur son téléphone en pleine nuit, écouteurs vissés aux oreilles.","Sa mère a poussé la porte pour vérifier comment on dormait. Elle a tout de suite vu la lueur de l'écran.","Mon cousin a paniqué, a balancé le téléphone et a fait semblant de dormir.","Résultat : ce matin, son père l'a sanctionné et traîné sur le chantier.","Mon autre cousine et moi, on a ri à en avoir mal au ventre.","Honnêtement, on était tellement soulagés que ce ne soit pas nous.","L'après-midi, j'ai étudié l'allemand, le français et l'anglais à l'intérieur.","J'ai aussi maintenu deux projets web et corrigé le bug de la vue annuelle du calendrier.","La devise du jour : bouger beaucoup, manger de la viande.","Un lapin rusé a trois terriers. J'y ai pensé toute la journée.","Chaque ressource autour de toi devrait être traitée comme un intérêt composé, pas comme du petit bois.","L'intérêt composé fait boule de neige. Le petit bois ne fait que brûler.","Stardew Valley, c'est pour les jours tranquilles. Quand on a de vrais projets, pas la peine de s'y perdre.","Scroller des vidéos courtes rend bête. Ma petite cousine en est la preuve vivante.","Je lui ai demandé si elle était un peu plus bête que moi. Elle a hoché la tête.","Alors je mange bien, j'apprends le web scraping, et je déploie des tâches sur GitHub Actions.","La durée de la vie n'est pas fixée par le ciel seul. Cultive ton bien-être, et tu auras de longues années. Voilà, c'était le thé du jour."]}:S.lang==="de"?{"2026-08-01":["Ich habe das heutige Tagebuch aufgeschlagen.","1. August. Hochsommer in Lianxi.","Heute meine Website gewartet.","Sogar ein paar Details aktualisiert, hier und da poliert.","Rick and Morty Erklärvideos geschaut. Richtig befriedigend.","Frühstück: nur Nudeln. Einfach.","Mittagessen: Gebratener Reis von gestern.","Dritt-Onkel nahm uns mit ins Wanda für Frosch und Garnelen.","Eine Hummerschuppe blieb an der Mandel kleben. Fast erstickt.","Beim Duschen hörte ich Dritt-Onkel meinen Cousin zum Lernen befragen.","Mein Cousin hatte null Selbstvertrauen bei den Hausaufgaben.","Wurde von seinem Vater runtergeputzt, schluchzte sogar.","Armer Junge. Versprach, von jetzt an jeden Tag mehr zu lernen.","Aber meine kleine Cousine ist viel cleverer. Sie kann mit ihrem Vater umgehen.","Dritt-Onkel ist super zufrieden mit seiner Tochter, kriegt Kopfweh bei seinem Sohn.","Ich habe den Verdacht, dass Dritt-Onkel einfach seine Tochter lieber mag.","Spät in der Nacht kam meine Cousine ins große Zimmer zum Schlafen.","Sie sagte: beim Widersprechen hat sie aus Versehen auf Papas Kopf gefurzt.","Weil er im Bett lag und sie daneben stand. Das braucht Mut.","Das war der Tee von heute."],"2026-08-02":["Ich habe das heutige Tagebuch aufgeschlagen.","2. August. Sommer in Lianxi geht weiter.","Morgens Instantnudeln und getrocknete Nudeln zusammen gekocht.","Instant plus Trocken. Eine Mischung, die nur ich erfinde.","Nachmittags meine eigene Domain newtnorlly.xyz gebunden.","Ging sofort durch. Viel reibungsloser als erwartet.","Dann nahm mich meine Cousine mit ihrem Sohn in die Spielhalle mit.","Mein Neffe wurde Erster am Rennautomaten, total stolz.","Im Auto krabbelte er von hinten rüber, um mir den Kopf zu tätscheln.","Als wäre ich sein Neffe. Rollen komplett vertauscht.","Habe zwei WeChat-Konten genutzt, um ihm 40 kostenlose Spielmarken zu holen.","Meine Cousine und ihre Freundin gingen shoppen, ließen den Kleinen bei mir.","Er ist so laut—meine Cousine nimmt ihn ungern mit zum Einkaufen.","Nach dem Chuanchuanxiang fuhr mich meine Cousine nach Hause.","Mein Neffe fragte ständig von der Rückbank: Onkel, kommst du zu uns?","Seine Mama brachte ihm einen Trick bei: Frag nach den letzten Tagen vor der Schule.","Also fragte er genau das, immer wieder, wie seine Mama es ihm gezeigt hatte.","Ich war so gerührt. Habe einfach sofort ja gesagt.","Ehrlich, zurzeit bin ich nicht wirklich begeistert, wenn mich jemand einlädt.","Aber am Telefon die Stimme meines Neffen: Onkel, Onkel, Onkel.","Konnte nicht anders. Tränen stiegen aus tiefstem Herzen auf.","Sollte nicht zu leichtfertig Kinder kriegen. Stell dir vor, so liebenswert wie Gan Dengdeng.","Gan Dengdeng ist der Spitzname meines Neffen. Mein Leben wäre übernommen.","Abends: Yulin Chuanchuanxiang. So heißt das Restaurant.","Keine öffentliche Toilette auf dem Rückweg gefunden.","Mein Onkel brachte einen Eimer Hähnchenunterkeulen von der Insel Sugeli mit.","Rick and Morty Erklärvideo geschaut. Die Phönix-Protokoll-Folge.","Rick hatte Lockvogel-Familien als falsche Ziele längst vorbereitet.","Feinde greifen die Lockvögel an. Der echte Rick bleibt unberührt.","Das war der Tee von heute."],"2026-07-31":["Ich habe das heutige Tagebuch aufgeschlagen.","31. Juli. Der Sommer in Lianxi hält sich noch.","Erst nach 11 Uhr aufgestanden. Tief geschlafen.","Das Lustigste: mein Cousin hat mitten in der Nacht heimlich mit Kopfhörern am Handy gespielt.","Seine Mutter stieß die Tür auf, um nach uns zu sehen, und sah sofort den Bildschirmschein.","Mein Cousin bekam Panik, warf das Handy weg und tat so, als würde er tief schlafen.","Heute Morgen wurde er von seinem Vater bestraft und auf die Baustelle geschleift.","Meine andere Cousine und ich haben uns kaputtgelacht.","Ehrlich gesagt, wir waren so erleichtert, dass es nicht uns erwischt hat.","Am Nachmittag habe ich drinnen Deutsch, Französisch und Englisch gelernt.","Außerdem zwei Webprojekte gepflegt und den Jahresansicht-Bug im Kalender behoben.","Das heutige Motto: viel bewegen, ordentlich Fleisch essen.","Ein schlauer Hase hat drei Baue. Daran habe ich den ganzen Tag gedacht.","Jede Ressource um dich herum sollte wie Zinseszins behandelt werden, nicht wie Anzündholz.","Zinseszins wächst. Anzündholz verbrennt einfach.","Stardew Valley ist für ruhige Tage. Wenn man echte Projekte hat, sollte man sich nicht in Spielen verlieren.","Kurzvideos scrollen macht dumm. Meine kleine Cousine ist der lebende Beweis.","Ich fragte sie, ob sie ein bisschen dümmer sei als ich. Sie hat tatsächlich genickt.","Also esse ich ordentlich, lerne Web Scraping und deploye Aufgaben auf GitHub Actions.","Des Lebens Dauer liegt nicht allein beim Himmel. Pfleg dein Wohl, und du wirst lange Jahre haben. Das war der Tee von heute."]}:{"2026-08-01":["我翻到了今天的日记。","八月一日，濂溪区的盛夏。","今天嘛，我维护好了自己的网站。","甚至还更新了一些小细节，一点一点地打磨。","看了瑞克和莫蒂的解说，感觉很过瘾。","早饭就是面条，简简单单。","午饭是炒饭，炒的是昨天的剩饭。","晚上三舅带我们去万达广场吃牛蛙和基围虾。","龙虾尾巴上的一个鳞片粘在扁桃体那里，差点呛死我。","晚上洗澡的时候，听到三舅找表弟问学习进度。","表弟对自己的功课一点底都没有。","又被老爹臭骂了一顿，还抽抽哒哒地哭了。","可怜的娃，还承诺以后每天多学几个单元。","但是表妹就机灵多了，对付老爹很有一套。","三舅看到女儿就满意得不行，看到儿子就头疼。","我甚至怀疑三舅就是嗯喜欢自己的女儿。","深夜的时候，表妹突然跑到大房间来睡。","她告诉我，反驳老爹的时候不小心对着他的头放了个屁。","因为老爹躺在床上，她站在床边反驳，气势十足。","以上，今天的茶话。"],"2026-08-02":["我翻到了今天的日记。","八月二日，濂溪区的夏天继续。","早上煮了面条，泡面和挂面一起煮的。","泡面加挂面，天下独一份的吃法。","下午绑定了我自己的专属域名，newtnorlly.xyz。","域名一下子就绑定成功了，比想象中顺利多了。","然后表姐带着我跟外甥去电动游戏城打电动。","外甥在赛车机上得了第一名，得意得很。","坐上副驾驶，外甥从后排爬过来摸我的头。","仿佛我是他的外甥一样，角色都反过来了。","我用两个微信账号多领了40个游戏币给他玩。","表姐和闺蜜去逛街，就把外甥丢给我带了。","外甥特别闹人，表姐逛街尽量不带上他。","晚上吃完串串香，表姐开车送我回家。","外甥在后排一直问我去不去他家。","他妈妈教了他一招：问舅舅上学前最后几天来不来。","外甥就学着他妈妈的说法，一直问我。","我当然很感动，就直接答应下来了。","说实话，现在有人约我出去我不是特别兴奋。","但是表姐电话那头外甥连喊三声舅舅舅舅舅舅。","我就情难自已，泪由心生。","以后不能轻易生小孩了，万一像甘凳凳这么可爱。","甘凳凳就是外甥的小名，我的人生会被他占据的。","晚上吃了玉林串串香，玉林串串香是个店名。","回来找公共厕所找了半天没找到。","舅舅从苏格里岛给我带了一桶鸡翅根做夜宵。","傍晚看了瑞克和莫蒂解说，瑞克的凤凰计划。","原来瑞克早准备好了复制人家庭做假目标。","让敌人打假目标，本体一点事都没有。","以上，今天的茶话。"],"2026-07-30":["我翻到了一页旧日记。","七月的倒数第二天。今天把熊猫主题打磨好了——黑胶唱片在左栏慢慢转着，波形条上下弹跳。粉绿黑三色圆卡终于不糊了。还修了幽灵Bug，日记四语切换也通了。窗外竹林沙沙响，橘猫蜷在膝盖上。","以上，就是今天的纪念日茶话了。"],"2026-07-31":["我翻到了今天的日记。","七月三十一日，濂溪区的夏天还没结束。","今天11点多才起床，睡得饱饱的。","好笑的是我表弟。他昨晚半夜偷偷玩手机，还戴着耳机。","他妈妈推门进来看我们睡得怎么样，一眼就看到他旁边的手机亮光。","我表弟吓得不轻，直接把手机一扔，在那儿装睡。","结果今天早上就被他老爹制裁了，带去工地上干活。","我和表妹在家里笑得合不拢嘴。","说真的，我们感觉很庆幸。还好不是我。","下午我在室内学了德语、法语，还有英语。","还维护了两个网站项目，修了日历的年视图Bug。","总之呢，今天的信条就是：多动，多吃肉。","我感觉狡兔三窟就该是这个意思。多给自己留几条路。","身边的一切资源，都应该当复利品去用，而不是消耗品。","复利品和消耗品是两个概念。一个是雪球，一个是柴火。","《星露谷物语》适合闲的时候玩，有正事就别沉迷。","刷短视频会让人变笨。我表妹就是活生生的例子。","我问她：表妹，你是不是比我笨一点？她居然点头了。","所以呢，我要吃得饱饱的，学爬虫，把任务部署到GitHub上。","盈缩之期，不但在天；养怡之福，可得永年。以上，今天的茶话。"]};var dk=new Date().toISOString().slice(0,10);var ms=as[dk]||as[Object.keys(as).sort().pop()];hm(ms[0]);var _aq=ms.slice(1);var _oi=0;var _oldNm=nm;var _h=document.getElementById("chatHint");if(_h){_h.hidden=false;uhint();}nm=function(){if(_oi<_aq.length){hm(_aq[_oi]);_oi++;if(_oi>=_aq.length){nm=_oldNm;var h=document.getElementById("chatHint");if(h)h.hidden=true;var gg=document.getElementById("guideOptions");gg.hidden=false;document.getElementById("chatThread").append(gg);}}else{_oldNm();}};if(_aq.length===0){nm=_oldNm;var h=document.getElementById("chatHint");if(h)h.hidden=true;var gg=document.getElementById("guideOptions");gg.hidden=false;document.getElementById("chatThread").append(gg);}}};});

function sw(n){if(!M.includes(n))return;S.module=n;document.getElementById("appShell").dataset.module=n;document.querySelectorAll("[data-view]").forEach(function(v){var active=v.dataset.view===n;v.removeAttribute("hidden");v.classList.toggle("is-active",active);if(!active){setTimeout(function(){if(!v.classList.contains("is-active"))v.setAttribute("hidden","");},280);}});document.querySelectorAll(".nav-item[data-module]").forEach(function(b){var a=b.dataset.module===n;b.classList.toggle("is-active",a);if(a)b.setAttribute("aria-current","page");else b.removeAttribute("aria-current");});document.getElementById("mainStage").scrollTop=0;if(n==="now")setTimeout(initCal,100);}
